# One-use patch to the verified deployed baseline. Removed before the release commit.
from pathlib import Path
import hashlib, json, subprocess
edits=json.loads(r'''[["mochi-room.js", "9da17099d035365d59d1543c1a90080da6896f374c07f170c32aa174e39e0391", "95a7656651c4498c6fe60d22bb88b3833d461b5dd8f17c7b249ae5bbc3180231", [[13, 13, " function fail(error){\n  failure=error?.message||'The browser reset the 3D view.';failed=true;\n  const previous=api;api=null;try{previous?.dispose();}catch(_){}\n  paint();\n }\n"], [15, 19, "  try{\n   const selected=root.MochiCatFriends.sync(S).selected;\n   if(typeof api.setFriends!=='function'||typeof api.getFriendCount!=='function')throw Error('The room graphics are from an older update. Retry 3D while online.');\n   api.setFriends(selected);\n   if(api.getFriendCount()!==selected.length)throw Error('Not all selected cat friends could be drawn. Their portraits are available above.');\n   api.setWear(S.worn||{});\n   const pet=root.MochiPlanner?.pet(root.MochiPlanner.init(S));\n   api.setGrowth(pet?.level||0);\n  }catch(error){fail(error);}\n }\n async function loadScene(){\n  // A failed classic-script request must not quietly remove every companion.\n  if(typeof root.MochiCatFriendsScene?.mount!=='function'){\n   const url=new URL('cat-friends-scene.js',script.src);url.searchParams.set('v',version);\n   await import(url.href);\n  }\n  if(typeof root.MochiCatFriends?.sync!=='function'||typeof root.MochiCatFriendsScene?.mount!=='function')throw Error('Cat Friends files are incomplete. Refresh while online; your saved progress is kept.');\n  let scene=await import(moduleURL.href);\n  if(scene.CAT_FRIENDS_VERSION!==1){\n   const fresh=new URL(moduleURL.href);fresh.searchParams.set('repair',String(Date.now()));\n   scene=await import(fresh.href);\n  }\n  if(scene.CAT_FRIENDS_VERSION!==1)throw Error('The room graphics need an online update. Your selected friends and progress are kept.');\n  return scene;\n"], [26, 27, "  $('room3dStatus').textContent=failed?'3D could not start: '+failure+' Your selected cat portraits are above; picture mode is still available.':pending?'Mochi is waking up…':'';\n"], [34, 35, "    const scene=await loadScene();\n"], [40, 41, "     onError:fail\n"], [43, 44, "   }catch(error){fail(error);console.warn('Mochi room unavailable:',error.message);}\n"]]], ["mochi-room-scene.js", "b936a29c96d91ed47803c66278233883a30b62ec1e359ef817ebf29a0bf7a824", "291b9a32f3201714b8061b30604a0b3e1d3b8245cdf807558d677fb3fa8d041c", [[0, 0, "// Checked by the room loader: legacy cached modules must not hide selected friends.\nexport const CAT_FRIENDS_VERSION=1;\n"], [345, 346, "if(typeof window.MochiCatFriendsScene?.mount!=='function')throw Error('Cat Friends graphics are not loaded.');\nfriends=window.MochiCatFriendsScene.mount(T,scene,{lite,onPet:info=>setMood(info.name+' leans into your hand. Prrr…')});\n"], [497, 498, " setWear,setGrowth,setFriends,getFriendCount:()=>friends.count,petFriend(id){const ok=friends?.pet(id)||false;if(ok){draw(0);wake();}return ok;},dispose,\n"]]], ["cat-friends-ui.js", "a43255dfaf1948389a7191e047ba75a53b9cbf23ff64fa51c978f0eb015f16a3", "2493cc1a51c6e015c767f7f8632a71d32583864c8537eef02e5cd91d13b7b3ed", [[24, 25, " const room=view.querySelector('.card.room')||view;\n const welcome=document.createElement('div');welcome.className='cf-room-welcome';\n welcome.innerHTML='<div><strong>Mochi + friends</strong><p id=\"catFriendsRoomSummary\" role=\"status\"></p></div><button type=\"button\" class=\"cf-toggle\" id=\"catFriendsManage\" aria-controls=\"catFriends\" aria-expanded=\"false\">Choose friends</button>';\n room.prepend(welcome);room.appendChild(box);\n document.getElementById('catFriendsManage').onclick=()=>{box.open=!box.open;if(box.open)box.scrollIntoView({block:'nearest'});};\n box.addEventListener('toggle',()=>document.getElementById('catFriendsManage').setAttribute('aria-expanded',String(box.open)));\n const roomLink=document.getElementById('tabRoom');if(roomLink)roomLink.textContent='Mochi + cat friends ↗';\n"], [26, 27, " welcome.after(pictures);\n"], [45, 46, "  // Keep the named visitors visible even if the 3D renderer is unavailable or out of view.\n  pictures.hidden=!r.selected.length;\n"], [47, 47, "  document.getElementById('catFriendsRoomSummary').textContent=r.selected.length\n   ?r.selected.map(id=>F.catalog.find(c=>c.id===id).name).join(', ')+' are visiting Mochi.'\n   :r.unlocked.length?'Your friends are resting. Choose friends to invite them back.'\n   :'No friends unlocked on this device yet ('+r.milestones+' earned milestones). Saved progress from another device needs to finish syncing.';\n"], [59, 60, " document.addEventListener('mochi:activity',paint);\n"]]], ["cat-friends.css", "edeaabd1b22e7faa0761a4e456ac6edec53886a7cbdfbae50a66a5d5179180e2", "9ac1755dc3a120dc84bf07766c385d61296a411b23f1944fac01b555966f1f19", [[20, 20, "\n/* A visible, renderer-independent roster precedes the room; no hidden unlock requirement. */\n.cf-room-welcome{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;padding:4px 0 8px;text-align:left}\n.cf-room-welcome strong{font-size:17px;color:#493453}.cf-room-welcome p{font-size:13px;line-height:1.5;margin:5px 0;color:#786584}\n.cf-room-welcome .cf-toggle{flex:0 0 auto;width:auto;min-width:112px}.cf-room-welcome+ .cf-picture-room{margin:0 auto 14px}\n@media(max-width:480px){.cf-room-welcome{align-items:flex-start}.cf-room-welcome .cf-toggle{min-width:98px;padding:9px;font-size:12px}.cf-room-welcome strong{font-size:16px}}\n"]]], ["release.json", "3985479b2230a2c45a5fca8a5a1e8a17bdd4d59a3fff971ad974b07e15fb10ca", "2c1e31ed30ddbdc453a767f42550dfe17f92cfa70125be4d3c011c3177cf59e1", [[1, 2, "  \"version\": \"5.5.1\",\n"], [3, 4, "  \"summary\": \"Cat friends are now visible by name at the top of the room in both 3D and picture mode. Missing companion graphics are recovered, and outdated room modules cannot silently show Mochi alone. Saved learning, coins and earned friends are preserved.\"\n"]]], ["CHANGELOG.md", "7083855f32f47237cdd2ab07101ae414e60245dbcd87feecb6b41bac576a829f", "aa281aa7ebc87ec4bf38f3950d66787a07778fdf1c95ba46fc4353fd9fc328db", [[0, 0, "# v5.5.1 — Keep Cat Friends visible and recover missing graphics\n\n- Put selected cat portraits, names and a Choose friends control at the top of the room in both viewing modes. Explain an empty or resting roster explicitly.\n- Retry the companion graphics dependency if its original request failed. Check the room module's companion capability before mounting, retry a stale module once with a fresh URL, and verify the rendered count matches the selected roster.\n- Fall back to the visible portraits with an explanatory status instead of silently presenting a Mochi-only 3D scene.\n- Preserve existing milestones, deliberate roster choices, learning data and rewards. No unlock thresholds are changed.\n- Add upgraded-state, missing-dependency and legacy-module regression tests; use synthetic progress in public tests.\n\n"]]], ["docs/CAT_FRIENDS.md", "e29151eba21101c8cbae3469adc8696ad9c0bb3f2190a230c68a5e01b53ad17b", "fa3de58295035aa0292fc0e054c5133a8bec918bcfe10c4c9f988f1e43af0c12", [[33, 33, "\n## v5.5.1 visibility and load recovery\n\nThe top of the room now always lists and displays the selected friends, including\nin 3D mode. Choose friends opens the roster. A deliberately empty roster stays\nempty and explains how to invite friends back; a device with no earned milestones\nshows that state instead of implying the feature is missing.\n\nThe room loader recovers a missing companion graphics script, checks the room\nmodule's `CAT_FRIENDS_VERSION` contract, retries an outdated module once, and\nchecks the renderer's companion count. If recovery fails it reports the error and\nkeeps picture companions available. The version label alone is not a graphics\nhealth check. This release does not change milestone thresholds or reset progress.\n"]]]]''')
for name, before, after, changes in edits:
    p=Path(name);raw=p.read_bytes()
    assert hashlib.sha256(raw).hexdigest()==before, 'Unexpected baseline: '+name
    lines=raw.decode().splitlines(keepends=True)
    for start,end,value in reversed(changes): lines[start:end]=[value]
    result=''.join(lines).encode()
    assert hashlib.sha256(result).hexdigest()==after, 'Unexpected patch: '+name
    p.write_bytes(result)
subprocess.run(['node','scripts/release.cjs'],check=True)
Path('.github/workflows/cat-friends-recovery.yml').unlink()
Path(__file__).unlink()
